 g=siege(0,2);g.battle->units[0].x=7;g.battle->units[0].y=4;g.battle->queue={0,100};int hp=g.battle->units[0].hp;check(!g.battleRoute(g.battle->units[0],{8,4}).empty()&&g.battleRoute(g.battle->units[0],{9,5}).empty(),"Walking route did not stop at first moat entry");check(g.act("move",{8,4}).empty()&&g.battle->units[0].hp==hp-70,"Castle moat did not charge entry damage");
