 g=siege();g.battle->units[0].unit=Archer;auto attacker=g.battle->units[0],defender=g.battle->units[1];int penalized=g.damage(attacker,defender,true);g.battle->siege.hp.fill(0);check(g.damage(attacker,defender,true)>=penalized*2,"Intact wall failed to halve attacker shooting");int base=g.damage(defender,attacker,true);g.battle->defenderSkills[Archery]=3;check(g.damage(defender,attacker,true)>base,"Defending hero's Archery was ignored");
 g=siege();int integrity=0;for(int n:g.battle->siege.hp)integrity+=n;for(int i=0;i<100;++i){++g.battle->round;g.catapultShots();}int after=0;for(int n:g.battle->siege.hp)after+=n;check(after<integrity,"Catapult never damaged fortifications");
 g=siege();g.battle->siege.fort=0;g.battle->queue={100,0};g.battle->defenderSpellbook=true;g.battle->defenderSpells[MagicArrow]=true;g.battle->defenderMana=20;g.battle->defenderPrimary[2]=3;hp=g.battle->units[0].hp;int humanMana=g.hero.mana;check(g.aiSpell()&&g.battle->units[0].hp<hp&&g.battle->defenderMana<20&&g.hero.mana==humanMana,"Computer hero did not use its own mana and spell target side");check(!g.aiSpell(),"Computer hero cast twice during one round");
 g=Game::create();g.hero.army={Stack{Marksman,100}};g.objectById(15)->army={Stack{Pikeman,1},Stack{Archer,50}};g.startBattle(15);g.battle->queue={0,100,101};g.battle->units[1].x=9;g.battle->units[1].y=5;g.battle->units[2].x=14;g.battle->units[2].y=4;hp=g.battle->units[2].hp;g.ai();check(g.battle&&g.battle->units[1].hp==Units[Pikeman].hp&&g.battle->units[2].hp<hp,"Battle AI chose a nearby token stack over the dangerous shooter");
