 auto save=std::filesystem::temp_directory_path()/("heroesiii-siege-story-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())+".json");check(g.save(save,error),"Story event state cannot be saved");Game restored;check(restored.load(save,error)&&restored.toJson()==g.toJson(),"Story markers failed save/load round trip");restored.runScenarioEvents();check(restored.resources==g.resources,"Loaded story reward was paid a second time");std::filesystem::remove(save);
 event["applies_to_human"]=0;event["applies_to_computer"]=1;event["day_of_first_occurence"]=3;event["resources"]["gold"]=777;g.scenarioRules["timedEvents"]=nlohmann::json::array({event});auto npc=g.playerResources[1][Gold];g.runScenarioEvents();check(g.playerResources[1][Gold]==npc+777&&g.resources[Gold]==1000,"Computer event altered the human treasury or skipped the computer");
 g.scenarioRules["additional"]["loss_condition"]={{"type",2},{"details",{{"days",3}}}};g.checkScenarioVictory();check(g.result==-1,"Map time limit did not trigger its loss condition");
